import {CMS,REFERENCE_DATE,SECTIONS,GG_OPTIONS,GG0130_ITEMS,GG0170_ITEMS,HEARING_OPTIONS,SPEECH_OPTIONS,PHQ_ITEMS,PHQ_LABELS,PHQ_OPTIONS,ICD10_SNF,MED_FLAGS,PDPM_RATES_FY2027,estimatePDPM,computeCAAs,demoAssessments,issues,progress,dayDiff,saveAssessment,completeReview,VENDORS,syntheticBundle,normalizeBundle,validDate} from './core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',chart:'M3 3v18h18 M7 14v3 M12 8v9 M17 4v13',connect:'M8 8l8 8 M7 3l-4 4 5 5 4-4z M17 12l-5 5 5 5 5-5z M14 2l-3 3 M22 10l-3 3',shield:'M12 3l8 4v6c0 5-8 9-8 9s-8-4-8-9V7z M8 12l3 3 5-6',book:'M12 6c-3-3-7-3-10-2v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2z M12 6v15',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',alert:'M12 3L2 21h20z M12 9v5 M12 17v.1',check:'M5 12l4 4L19 6',building:'M4 22V4h16v18 M8 8h1 M15 8h1 M8 12h1 M15 12h1 M10 22v-6h4v6',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v12 M6 9l6 6 6-6 M4 17v4h16v-4',menu:'M3 6h18 M3 12h18 M3 18h18',close:'M6 6l12 12 M18 6L6 18'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.file}"/></svg>`;
const state={assessments:demoAssessments(),records:[],quarantine:[],duplicates:0,logs:[],plans:{},section:'Cognition',filter:'all',query:'',asof:REFERENCE_DATE};
try{const saved=JSON.parse(sessionStorage.getItem('tabula-mds-workspace-v1'));if(saved&&saved.schema===1&&Array.isArray(saved.assessments)){Object.assign(state,saved);state.filter='all';state.query='';}}catch{}
function persist(){try{sessionStorage.setItem('tabula-mds-workspace-v1',JSON.stringify({...state,schema:1}));return true;}catch{toast('Browser storage is unavailable. Changes will last only until you reload.');return false;}}
function log(action,detail){state.logs.unshift({at:new Date().toISOString(),action,detail});state.logs=state.logs.slice(0,300);persist();}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
function formatDate(d){return validDate(d)?new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}):'Set date';}
const chip=(s,c='')=>`<span class="chip ${c}"><span class="dot"></span>${esc(s)}</span>`;
function route(){return (location.hash.slice(1)||'overview').split('/');}
function go(s){location.hash=s;}
function filtered(){return state.assessments.filter(a=>(!state.query||[a.name,a.id,a.type,a.owner].join(' ').toLowerCase().includes(state.query.toLowerCase()))&&(state.filter==='all'||state.filter==='soon'&&dayDiff(a.due,state.asof)<=3&&a.status!=='Review complete'||state.filter==='incomplete'&&a.status!=='Review complete'||state.filter==='complete'&&a.status==='Review complete'));}
function render(){const [page,id]=route();const active=page==='assessment'?'assessments':page;const nav=[['overview','Overview','grid'],['assessments','Assessments','file'],['residents','Residents','people'],['calendar','Assessment calendar','calendar'],['quality','Quality & readiness','chart'],['integrations','Integrations','connect'],['audit','Activity log','shield'],['resources','CMS reference desk','book']];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#overview"><div class="logo">✳</div><div><strong>Tabula Medica</strong><small>MDS WORKSPACE</small></div></a><div class="navlabel">CARE OPERATIONS</div>${nav.map((n,i)=>`${i===5?'<div class="navlabel">WORKSPACE</div>':''}<button class="nav ${active===n[0]?'active':''}" data-go="${n[0]}">${icon(n[2])}${n[1]}${n[0]==='assessments'?'<span class="count">'+state.assessments.length+'</span>':''}</button>`).join('')}<div class="sidebar-bottom"><div class="release-box"><strong>October 2026 reference</strong>RAI ${CMS.rai} · FY2027 PDPM<br>Full CMS engine not connected</div><div class="profile"><span class="avatar">TM</span><div style="font-size:11px">Demo coordinator<br><small>SYNTHETIC WORKSPACE</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="facility"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><div class="facility-icon">${icon('building')}</div><div><strong>Willow Creek Care Center</strong><small>Training facility · Synthetic residents</small></div></div><div class="top-actions"><div class="search">${icon('search')}<input id="global-search" aria-label="Search assessments" placeholder="Search residents or assessments" value="${esc(state.query)}"></div>${chip('Demo environment')}<span class="avatar">TM</span></div></header><div class="demo-bar"><span><b>Demonstration workspace</b> · Synthetic records only. Saved in this browser tab; no live EHR connection.</span><a href="/login">Existing app sign-in ↗</a></div><main class="main" id="main" tabindex="-1">${page==='assessment'?assessmentPage(id):page==='integrations'?integrationPage():page==='calendar'?calendarPage():page==='residents'?residentsPage():page==='quality'?qualityPage():page==='audit'?auditPage():page==='resources'?resourcesPage():page==='assessments'?listPage():overview()}<footer class="footer"><span>Tabula Medica · Designed around better resident care</span><span>Local demonstration · No CMS submission or billing calculation</span></footer></main></div></div>`;bind();}
function heading(eyebrow,title,desc,actions=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`;}
function metrics(){const all=state.assessments;const open=all.filter(a=>a.status!=='Review complete');const soon=open.filter(a=>dayDiff(a.due,state.asof)<=3).length;const complete=all.length-open.length;const coverage=all.length?Math.round(all.reduce((t,a)=>t+progress(a),0)/all.length):0;return `<div class="metrics">${[['Open assessments',open.length,'Assigned across your care team','file',''],['Due within 3 days',soon,'Internal targets · includes overdue','clock','highlight'],['Evidence reviewed',coverage+'%','Across eight workflow sections','shield',''],['Review complete',complete,'Local reviews · not CMS accepted','check','']].map(m=>`<div class="metric ${m[4]}"><div class="metric-top"><span>${m[0]}</span>${icon(m[3])}</div><div class="value number">${m[1]}</div><div class="desc">${m[2]}</div></div>`).join('')}</div>`;}
function filters(){return `<div class="filters">${[['all','All assessments'],['soon','Due soon'],['incomplete','In progress'],['complete','Review complete']].map(f=>`<button class="filter ${state.filter===f[0]?'active':''}" data-filter="${f[0]}">${f[1]}</button>`).join('')}</div>`;}
function assessmentTable(rows=filtered()){return `<div class="table-scroll"><table><thead><tr><th>Resident</th><th>Assessment</th><th>Internal target</th><th>Review</th><th>Owner</th><th></th></tr></thead><tbody>${rows.map(a=>{const d=dayDiff(a.due,state.asof);return `<tr><td><div class="resident"><span class="avatar">${esc(initials(a.name))}</span><div><strong>${esc(a.name)}</strong><small>Room ${esc(a.room)} · ${esc(a.id)}</small></div></div></td><td>${esc(a.type)}<span class="sub">ARD ${formatDate(a.ard)}</span></td><td>${formatDate(a.due)}<span class="sub" style="color:${d<0?'#b66a50':d<=3?'#aa8a46':'#8d9b92'}">${d<0?Math.abs(d)+'d overdue':d===0?'Today':d+' days away'}</span></td><td><span class="number">${progress(a)}%</span><div class="progress"><span style="width:${progress(a)}%"></span></div></td><td><span class="avatar" title="Assigned coordinator ${esc(a.owner)}">${esc(a.owner)}</span></td><td><button class="reviewlink" data-go="assessment/${a.id}">Review →</button></td></tr>`;}).join('')||'<tr><td colspan="6"><div class="empty">No assessments match this view.<br>Try another filter or clear your search.</div></td></tr>'}</tbody></table></div>`;}
function overview(){return heading('YOUR DAILY WORKSPACE','Carefully documented. Confidently reviewed.','A clear view of every assessment, its evidence, and what needs your attention.',`<button data-action="export">Export worklist</button><button class="primary" data-action="new">+ New assessment</button>`)+metrics()+`<div class="two-col"><div><section class="panel"><div class="panelhead"><div><h2>Assessment worklist</h2><p>Keep your team focused on the next right step.</p></div><button class="quiet" data-go="assessments">View all →</button></div>${filters()}${assessmentTable(filtered().slice(0,5))}<div class="rowfooter"><span>${filtered().length} assessments in this view</span><span>As of ${formatDate(state.asof)}, 2026</span></div></section><section class="panel"><div class="panelhead"><div><h2>The week ahead</h2><p>Coordinator-defined targets are kept separate from CMS regulatory deadlines.</p></div><button class="quiet" data-go="calendar">Open calendar →</button></div>${week()}</section></div><div class="rightcol"><section class="panel"><div class="panelhead"><h2>Needs your attention</h2>${chip('3 items','amber')}</div><div class="attention"><div class="icon-wrap">${icon('file')}</div><div><strong>Clinical evidence is incomplete</strong><p>Review source notes before completing the selected MDS items.</p><button class="quiet" data-go="assessment/${state.assessments[0]?.id}">Review assessment →</button></div></div><div class="attention"><div class="icon-wrap">${icon('connect')}</div><div><strong>Connect your source systems</strong><p>PCC and MatrixCare require facility authorization and vendor access.</p><button class="quiet" data-go="integrations">Plan connections →</button></div></div><div class="attention"><div class="icon-wrap">${icon('book')}</div><div><strong>October 2026 CMS references</strong><p>Current references and future drafts are tracked separately.</p><button class="quiet" data-go="resources">View release desk →</button></div></div></section><section class="panel"><div class="panelhead"><h2>Integration readiness</h2></div>${VENDORS.slice(0,2).map(v=>`<div class="integration-mini"><div class="vendor-icon" style="color:${v.color}">${v.initials}</div><div><strong>${v.name}</strong><span class="sub">${state.plans[v.id]?'Plan saved':'Setup required'}</span></div>${chip('Not connected','gray')}</div>`).join('')}<div class="pad" style="padding:15px 20px"><button class="quiet" data-go="integrations">Open integration workbench →</button></div></section></div></div>`;}
function week(){return `<div class="timeline">${Array.from({length:7},(_,i)=>{const d=new Date(state.asof+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i);const iso=d.toISOString().slice(0,10),num=state.assessments.filter(a=>a.due===iso).length;return `<div class="timeline-day ${i===0?'active':''}">${d.toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'})}<b>${d.getUTCDate()}</b><div style="height:9px" aria-label="${num} assessments due">${'<span></span>'.repeat(num)}</div></div>`;}).join('')}</div><div class="timeline-legend">● Assessment target date · Reference day ${esc(state.asof)}</div>`;}
function listPage(){return heading('ASSESSMENT OPERATIONS','Your assessment worklist','Track preparation and evidence review. Full CMS validation remains a separate launch requirement.',`<button data-action="export">Export worklist</button><button class="primary" data-action="new">+ New assessment</button>`)+metrics()+`<section class="panel"><div class="panelhead"><h2>All assessments</h2><input id="list-search" aria-label="Filter assessments" placeholder="Search name, type or coordinator" value="${esc(state.query)}"></div>${filters()}${assessmentTable()}<div class="rowfooter">${filtered().length} of ${state.assessments.length} assessments</div></section>`;}
function sectionForm(a,s){
  const dx=a.items.diagnoses||[];
  const meds=a.items.meds||[];
  const phqDone=PHQ_ITEMS.filter(k=>a.items['D0200'+k]!==undefined&&a.items['D0200'+k]!=='').length;
  const phqTotal=phqDone===9?PHQ_ITEMS.reduce((t,k)=>t+parseInt(a.items['D0200'+k]||'0',10),0):null;
  const phqSeverity=phqTotal===null?'':phqTotal>=15?'Severe':phqTotal>=10?'Moderate':phqTotal>=5?'Mild':'Minimal';
  if(s==='Cognition')return `<div class="field-block"><h3 class="section-title">C · BIMS &amp; Cognitive Patterns</h3><label>C0500 · BIMS Summary Score<select name="C0500"><option value="">Select a reviewed score</option>${Array.from({length:16},(_,i)=>String(i).padStart(2,'0')).concat(['99']).map(v=>`<option value="${v}" ${a.items.C0500===v?'selected':''}>${v}${v==='99'?' — Unable to complete interview':''}</option>`).join('')}</select></label><div class="fieldnote">Enter a documented score after reviewing the complete interview and applicable CMS instructions. Score 00–07 = severe impairment; 08–12 = moderate; 13–15 = intact. Score 99 = unable to complete.</div></div><div class="field-block" style="margin-top:16px"><h3 class="section-title">B · Hearing, Speech &amp; Vision</h3><label style="display:block;margin-bottom:12px">B0200 · Hearing<select name="B0200" style="margin-top:5px"><option value="">Not assessed</option>${Object.entries(HEARING_OPTIONS).map(([v,l])=>`<option value="${v}" ${(a.items.B0200||'')===v?'selected':''}>${v} — ${esc(l)}</option>`).join('')}</select></label><label style="display:block;margin-bottom:12px">B0700 · Makes self understood<select name="B0700" style="margin-top:5px"><option value="">Not assessed</option>${Object.entries(SPEECH_OPTIONS).map(([v,l])=>`<option value="${v}" ${(a.items.B0700||'')===v?'selected':''}>${v} — ${esc(l)}</option>`).join('')}</select></label><label style="display:block">B1000 · Vision<select name="B1000" style="margin-top:5px"><option value="">Not assessed</option><option value="0" ${a.items.B1000==='0'?'selected':''}>0 — Adequate vision</option><option value="1" ${a.items.B1000==='1'?'selected':''}>1 — Impaired — difficulty reading, watching television</option><option value="2" ${a.items.B1000==='2'?'selected':''}>2 — Moderately impaired — limited vision; not able to read</option><option value="3" ${a.items.B1000==='3'?'selected':''}>3 — Highly impaired — object identification in question</option></select></label><div class="fieldnote" style="margin-top:8px">Hearing and communication ability influence SLP PDPM. Confirm against direct observation and clinical notes.</div></div>`;
  if(s==='Mood')return `<div class="field-block"><h3 class="section-title">D0200 · PHQ-9 Mood Interview</h3><div class="fieldnote">Rate how often each symptom occurred over the past 14 days. Complete all 9 items for a total score.</div><table class="phq-table"><thead><tr><th style="text-align:left">Symptom</th><th>Frequency</th></tr></thead><tbody>${PHQ_ITEMS.map(k=>`<tr><td class="phq-symptom">${k}. ${esc(PHQ_LABELS[k])}</td><td><select name="D0200${k}"><option value="">—</option>${Object.entries(PHQ_OPTIONS).map(([v,l])=>`<option value="${v}" ${a.items['D0200'+k]===v?'selected':''}>${v} — ${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>${phqTotal!==null?`<div class="evidence" style="margin-top:14px">PHQ-9 total: <strong>${phqTotal}/27</strong> — <strong>${phqSeverity}</strong> depression symptom severity<small>Demonstration scoring only. Clinical interpretation requires licensed clinician review.</small></div>`:`<div class="fieldnote" style="margin-top:14px">${phqDone}/9 items completed</div>`}</div>`;
  if(s==='Function')return `<div class="field-block"><h3 class="section-title">GG · Functional Abilities &amp; Goals — Admission Performance</h3><div class="fieldnote">Rate performance during the first 3 days of the PPS stay (admission performance). Do not infer usual performance from one observation. Future draft response value 12 is excluded.</div><h4 style="font-size:12px;margin:16px 0 8px;color:#4a5e50;font-weight:600">GG0130 · Self-Care</h4>${GG0130_ITEMS.map(gi=>`<label style="margin-bottom:12px;display:block;font-size:12px">GG0130${esc(gi.id)} · ${esc(gi.label)}<select name="GG0130_${esc(gi.id)}" style="margin-top:4px"><option value="">Not assessed</option>${Object.entries(GG_OPTIONS).map(([v,l])=>`<option value="${v}" ${(a.items['GG0130_'+gi.id]||(gi.id==='A1'?a.items.GG0130A1:''))===v?'selected':''}>${v} — ${esc(l)}</option>`).join('')}</select></label>`).join('')}<h4 style="font-size:12px;margin:16px 0 8px;color:#4a5e50;font-weight:600">GG0170 · Mobility</h4>${GG0170_ITEMS.map(gi=>`<label style="margin-bottom:12px;display:block;font-size:12px">GG0170${esc(gi.id)} · ${esc(gi.label)}<select name="GG0170_${esc(gi.id)}" style="margin-top:4px"><option value="">Not assessed</option>${Object.entries(GG_OPTIONS).map(([v,l])=>`<option value="${v}" ${(a.items['GG0170_'+gi.id]||'')===v?'selected':''}>${v} — ${esc(l)}</option>`).join('')}</select></label>`).join('')}<div class="fieldnote" style="margin-top:8px">GG0130A1 (Eating) drives PT and OT PDPM case-mix groups. All items require documented clinical observation.</div></div>`;
  if(s==='Diagnoses')return `<div class="field-block"><h3 class="section-title">Section I · Active diagnoses</h3><div class="fieldnote">Select diagnoses active during the 7-day look-back period. NTA comorbidity weights shown for reference; weights require full NTA grouper validation.</div><div class="dx-grid">${ICD10_SNF.map(d=>`<label class="dx-item"><input type="checkbox" name="diagnosis" value="${esc(d.code)}" ${dx.includes(d.code)?'checked':''}><span style="flex:1"><span style="display:block;font-size:11px;font-weight:600">${esc(d.code)}</span><span style="display:block;font-size:10px;color:#6a7e70;line-height:1.4">${esc(d.label)}</span></span>${d.nta>0?`<span class="nta">NTA +${d.nta}</span>`:''}</label>`).join('')}</div></div>`;
  if(s==='Skin')return `<div class="field-block"><h3 class="section-title">Section M · Skin conditions</h3><div class="fieldnote">Document pressure ulcer risk assessment and current skin conditions.</div><div style="margin-top:14px"><label>M0100 · Pressure ulcer risk assessment determination<select name="M0100" style="margin-top:7px"><option value="">Not assessed</option><option value="0" ${a.items.M0100==='0'?'selected':''}>0 — No risk factors identified</option><option value="1" ${a.items.M0100==='1'?'selected':''}>1 — At risk for or has a pressure ulcer</option></select></label></div><div style="margin-top:14px"><label>M0210 · Worst pressure ulcer stage (if present)<select name="M0210" style="margin-top:7px"><option value="">None present / not assessed</option><option value="1" ${a.items.M0210==='1'?'selected':''}>Stage 1 — Non-blanchable erythema of intact skin</option><option value="2" ${a.items.M0210==='2'?'selected':''}>Stage 2 — Partial thickness skin loss</option><option value="3" ${a.items.M0210==='3'?'selected':''}>Stage 3 — Full thickness skin loss</option><option value="4" ${a.items.M0210==='4'?'selected':''}>Stage 4 — Full thickness tissue loss</option><option value="U" ${a.items.M0210==='U'?'selected':''}>Unstageable</option><option value="DTI" ${a.items.M0210==='DTI'?'selected':''}>Deep tissue injury</option></select></label></div></div>`;
  if(s==='Medications')return `<div class="field-block"><h3 class="section-title">Section N · Medications administered</h3><div class="fieldnote">Check medications administered on any of the last 7 days. NTA point values shown for reference only; requires full NTA grouper validation.</div><div class="med-grid">${MED_FLAGS.map(m=>`<label class="med-item"><input type="checkbox" name="med" value="${esc(m.id)}" ${meds.includes(m.id)?'checked':''}><span style="flex:1;font-size:11px">${esc(m.label)}<span style="display:block;font-size:9px;color:#8a9a82">${esc(m.id)}</span></span><span class="nta">NTA +${m.nta}</span></label>`).join('')}</div></div>`;
  if(s==='Care areas'){const caas=computeCAAs(a.items);const triggered=caas.filter(c=>c.triggered);return `<div class="field-block"><h3 class="section-title">Section V · Care Area Assessments (CAAs)</h3><div class="fieldnote">CAA triggers are computed automatically from MDS items collected in other sections. Review triggered care areas and document care plan rationale in the evidence note.</div><div style="margin-top:14px">${caas.map(c=>`<div style="display:flex;justify-content:space-between;align-items:flex-start;padding:10px 14px;margin-bottom:6px;background:${c.triggered?'#f0faf2':'#f8f8f7'};border-left:3px solid ${c.triggered?'var(--teal)':'#cdd8c8'};border-radius:4px"><div><strong style="font-size:12px">${esc(c.id)} · ${esc(c.label)}</strong><p style="font-size:11px;color:#7a8c70;margin:3px 0 0;line-height:1.4">${esc(c.basis)}</p></div><span style="font-size:10px;font-weight:600;white-space:nowrap;margin-left:12px;color:${c.triggered?'var(--teal)':'#9aab90'}">${c.triggered?'▶ TRIGGERED':'Not triggered'}</span></div>`).join('')}</div>${triggered.length>0?`<div style="margin-top:12px;padding:12px;background:#f0faf2;border-radius:6px;border:1px solid #cce8d4"><strong style="font-size:12px;color:var(--teal)">${triggered.length} care area${triggered.length>1?'s':''} triggered</strong><p style="font-size:11px;color:#4a6e50;margin:4px 0 0">Document care plan rationale in the evidence note below. A production CAA review requires all MDS sections and licensed clinician judgment.</p></div>`:''}<div class="notice" style="margin-top:14px">CAA triggers shown here are based on items collected in this workspace only. See RAI ${CMS.rai} Chapter 4 for official trigger criteria and required care plan documentation.</div></div>`;}
  if(s==='Administration'){return `<div class="field-block"><h3 class="section-title">Section Z · Assessment Administration</h3><div class="fieldnote">Document assessment type, completion status, and coordinator certification. These are planning fields only — electronic signatures and CMS iQIES submission are not active in this demonstration.</div><div style="margin-top:14px"><label>Z0100A · Medicare Part A PPS assessment?<select name="Z0100A" style="margin-top:5px"><option value="">Not specified</option><option value="1" ${a.items.Z0100A==='1'?'selected':''}>Yes — Medicare PPS required</option><option value="0" ${a.items.Z0100A==='0'?'selected':''}>No</option></select></label></div><div style="margin-top:12px"><label>Z0200A · Assessment type designation<select name="Z0200A" style="margin-top:5px"><option value="">Not specified</option><option value="01" ${a.items.Z0200A==='01'?'selected':''}>01 — OBRA Required Assessment</option><option value="02" ${a.items.Z0200A==='02'?'selected':''}>02 — PPS Required Assessment</option><option value="03" ${a.items.Z0200A==='03'?'selected':''}>03 — OBRA and PPS Required</option><option value="99" ${a.items.Z0200A==='99'?'selected':''}>99 — Not Applicable</option></select></label></div><div style="margin-top:12px"><label>Z0400 · Person completing this assessment (name/credential)<input name="Z0400" maxlength="80" placeholder="Coordinator name and credential (demo only)" value="${esc(a.items.Z0400||'')}" style="margin-top:5px"></label></div><div style="margin-top:12px"><label>Z0500B · Date RN assessment coordinator signed assessment<input type="date" name="Z0500B" value="${esc(a.items.Z0500B||'')}" style="margin-top:5px"></label></div><div class="notice" style="margin-top:16px"><b>Clinical signatures and CMS submission are not active.</b> An RN assessment coordinator must certify each MDS before CMS iQIES submission. iQIES SFTP credentials, official edit checks, and submission pipelines are required for clinical use.</div></div>`;}
  return `<div class="notice">Document the ${s.toLowerCase()} review and the sources used. The full section's structured MDS items and skip logic are not implemented in this demonstration.</div>`;
}
function pdpmPanel(a){
  const p=estimatePDPM(a.items);
  const components=[['PT',p.ptRate,'GG0130A1: '+(p.gg||'—')],['OT',p.otRate,'GG functional score'],['SLP',p.slpRate,'BIMS: '+(p.bims===null?'—':p.bims)+(p.cogFlag?' (cog flag)':'')],['Nursing',p.nursingRate,'Standard case-mix'],['NTA',p.ntaRate,'Score: '+p.ntaScore+'/43']];
  const maxRate=Math.max(...components.map(c=>c[1]));
  return `<section class="panel"><div class="panelhead"><div><h2>PDPM estimate</h2><p>Demo only · Simplified adjustments · Not CMS grouper ${CMS.grouper}</p></div>${chip('FY2027 rates','gray')}</div><div class="pad"><div style="font-size:11px;color:#8a9b80;margin-bottom:16px;line-height:1.6">Updated after each save. Add diagnoses and medications in their sections to refine the NTA estimate.</div>${components.map(c=>`<div class="barrow" style="margin:10px 0"><span style="width:65px;font-size:11px;color:#627264">${c[0]}</span><div class="progress" style="flex:1;height:8px"><span style="width:${Math.round(c[1]/maxRate*100)}%"></span></div><div style="width:95px;text-align:right;font-size:11px"><b style="font-variant-numeric:tabular-nums">$${c[1]}</b><span style="color:#90a082;font-size:9px;display:block">${c[2]}</span></div></div>`).join('')}<div class="pdpm-total-row"><span class="label">Est. per diem</span><span class="amount">$${p.total}</span></div><div style="font-size:10px;color:#8a9b80;margin-top:10px">+ $${PDPM_RATES_FY2027.ncm} non-case-mix · Total includes all components</div><div class="notice" style="margin-top:14px;font-size:10px">Not CMS grouper output. Not a payment guarantee. Run the official grouper ${CMS.grouper} with FY2027 ICD-10 mappings before using for billing.</div></div></section>`;
}
function assessmentPage(id){
  const a=state.assessments.find(x=>x.id===id);
  if(!a)return '<div class="empty">Assessment not found. <a href="#assessments">Return to assessments</a></div>';
  const s=SECTIONS.includes(state.section)?state.section:'Cognition';
  const errors=issues(a);
  const evidenceNote=s==='Function'?'Synthetic nursing note: staff provided supervision during the observed meal.':s==='Cognition'?'Synthetic interview packet: the BIMS summary must be confirmed against the completed resident interview.':s==='Diagnoses'?'Synthetic medical record: confirm active diagnoses against physician-signed problem list and look-back documentation.':s==='Medications'?'Synthetic medication administration record (MAR): verify each medication against the facility eMAR.':s==='Mood'?'Synthetic interview packet: complete the PHQ-9 via direct interview per Section D instructions.':s==='Skin'?'Synthetic wound assessment note: confirm staging with licensed nurse skin assessment.':'Synthetic '+s.toLowerCase()+' packet: confirm the relevant notes, dates, and reviewer before completing this section.';
  return heading('ASSESSMENTS / '+esc(a.id),esc(a.name),esc(a.type)+' · Room '+esc(a.room)+' · Synthetic resident',`<button data-go="assessments">← Worklist</button><button data-action="edit-meta" data-id="${a.id}">Edit details</button><button class="primary" data-action="save" data-id="${a.id}">Save review</button>`)+`<div class="assessment-summary"><div>Assessment reference date<strong>${formatDate(a.ard)}</strong></div><div>Internal completion target<strong>${formatDate(a.due)}</strong></div><div>Coordinator<strong>${esc(a.owner)}</strong></div><div>Evidence coverage<strong>${progress(a)}%</strong></div><div>Status<strong>${esc(a.status)}</strong></div><div>Revision<strong>${a.revision}</strong></div></div><div class="detail-grid"><section class="panel"><div class="panelhead"><h2>Review sections</h2></div><div class="sectionlist">${SECTIONS.map(t=>`<button class="sectionbutton ${t===s?'active':''}" data-section="${t}"><span>${t}</span><span style="color:${a.sections[t].reviewed?'#559052':'#c0cbb3'}">${a.sections[t].reviewed?'✓':'○'}</span></button>`).join('')}</div></section><div><section class="panel"><div class="panelhead"><div><h2>${s} review</h2><p>Selected fields for workflow demonstration. Not a complete MDS item set.</p></div>${chip(a.sections[s].reviewed?'Reviewed':'Needs review',a.sections[s].reviewed?'':'amber')}</div><div class="pad"><form id="section-form" data-id="${a.id}">${sectionForm(a,s)}<div class="field-block"><h3 style="font-size:13px;margin-top:0">Source evidence</h3><div class="evidence">${esc(evidenceNote)}<small>Demonstration source · Not imported from an EHR · ${esc(a.id)}</small></div></div><div class="field-block"><label>Evidence and review note<textarea name="note" maxlength="3000" placeholder="Use synthetic notes only. Record source, date, and review rationale.">${esc(a.sections[s].note)}</textarea></label><label class="check"><input type="checkbox" name="reviewed" ${a.sections[s].reviewed?'checked':''}>I reviewed the synthetic source evidence for this section.</label></div><div style="display:flex;gap:10px;margin-top:20px"><button class="primary" type="submit">Save section review</button><button type="button" data-action="validate" data-id="${a.id}">Check review gaps</button></div></form></div></section><section class="panel"><div class="panelhead"><div><h2>Review gate</h2><p>${errors.length} outstanding checks in this demonstration</p></div>${chip(errors.length?'Needs work':'Checks passed',errors.length?'amber':'')}</div><div class="pad">${errors.length?`<ul class="errors">${errors.slice(0,4).map(e=>`<li>${esc(e.text)}</li>`).join('')}</ul>${errors.length>4?`<p class="current-note">+ ${errors.length-4} additional checks. Open all review gaps to inspect.</p>`:''}`:'<div class="notice">The local checklist is complete. Clinical sign-off, official CMS edit validation and iQIES acceptance remain separate.</div>'}<div style="display:flex;gap:10px;margin-top:18px"><button data-action="validate" data-id="${a.id}">View all review gaps</button><button class="primary" data-action="complete" data-id="${a.id}" ${errors.length||a.status==='Review complete'?'disabled':''}>Mark local review complete</button></div><p class="fieldnote">Any edit reopens the review. This action is not an electronic clinical signature and does not transmit an assessment.</p></div></section>${pdpmPanel(a)}</div></div>`;
}
function integrationPage(){return heading('CONNECTED CARE','Integration workbench','Bring source evidence into a reviewable workflow. Every connection starts with verified access.',`<button data-action="export-plans">Export connection plans</button>`)+`<div class="notice warning"><b>No live connections.</b> Vendor adapters need approved API specifications, facility authorization, server-side credentials, and a validated clinical backend. This workbench tests only a generic FHIR R4 normalization path.</div><div class="grid2" style="margin-bottom:23px">${VENDORS.map(v=>`<section class="vendor-card"><div class="cardtop"><div class="vendor-icon" style="color:${v.color}">${v.initials}</div>${chip(state.plans[v.id]?'Plan saved · offline':'Not connected','gray')}</div><h3>${v.name}</h3><span class="eyebrow" style="font-size:9px">${v.category}</span><p>${v.description}</p><button data-action="plan" data-vendor="${v.id}">${state.plans[v.id]?'Edit connection plan':'Set up connection plan'} →</button></section>`).join('')}</div><section class="panel"><div class="panelhead"><div><h2>FHIR R4 sample workbench</h2><p>Normalize source resources, preserve provenance, and quarantine conflicts.</p></div><button class="primary" data-action="sample">Process synthetic sample</button></div><div class="pad"><div class="grid3">${[['Imported resources',state.records.length],['Duplicate events skipped',state.duplicates],['Quarantined resources',state.quarantine.length]].map(x=>`<div class="metric"><div class="metric-top">${x[0]}</div><div class="value">${x[1]}</div></div>`).join('')}</div><p class="fieldnote">Reprocess the sample to test idempotency. Resource IDs are scoped to the demo facility. Source changes require human reconciliation; demographic matching is never automatic.</p>${state.records.length?`<div class="table-scroll"><table class="mapping"><thead><tr><th>Source resource</th><th>Resident reference</th><th>Normalized evidence</th><th>Review state</th></tr></thead><tbody>${state.records.map(r=>`<tr><td>${esc(r.resourceType)}<span class="sub">${esc(r.sourceId)}</span></td><td>${esc(r.patientId)}</td><td>${esc(r.label)}</td><td>${chip('Needs human review','amber')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your source-to-evidence workflow starts here.<br>Process the bundled synthetic sample to inspect the normalized records.</div>'}<details><summary>Inspect the synthetic FHIR source</summary><pre class="codebox">${esc(JSON.stringify(syntheticBundle(),null,2))}</pre></details><div style="display:flex;gap:9px;flex-wrap:wrap"><button data-action="changed-sample">Test changed-source quarantine</button><button data-action="download-sample">Download sample JSON</button></div>${state.quarantine.length?`<ul class="errors">${state.quarantine.map(q=>`<li>${esc(q.type)} · ${esc(q.reason)}</li>`).join('')}</ul>`:''}</div></section><section class="panel"><div class="panelhead"><div><h2>Facility NPI verification</h2><p>Look up CMS NPI Registry data for any provider or organization. Live API — real results.</p></div>${chip('Live CMS API','')}</div><div class="pad"><div style="display:flex;gap:10px;align-items:flex-end;max-width:460px"><label style="flex:1">NPI number (10 digits)<input id="npi-input" maxlength="10" placeholder="1234567890" style="margin-top:5px;font-size:14px"></label><button data-action="npi-lookup" style="white-space:nowrap">Look up →</button></div><div id="npi-result" style="margin-top:14px"></div><p class="fieldnote" style="margin-top:8px">CMS NPPES NPI Registry · Public API · Returns real provider data · Not linked to this synthetic facility</p></div></section>`;}
function calendarPage(){return heading('ASSESSMENT PLANNING','A little more room to plan.','Coordinator-defined targets are kept separate from CMS regulatory deadlines.',`<button data-action="change-date">Change reference day</button>`)+`<div class="notice">These are internal planning dates. An official scheduling engine must account for assessment type, stay history, look-back periods, and applicable CMS rules before calculating regulatory deadlines.</div><section class="panel"><div class="panelhead"><h2>Next seven days</h2><span class="current-note">Reference: ${esc(state.asof)}</span></div>${week()}</section><section class="panel"><div class="panelhead"><h2>Upcoming internal targets</h2></div>${assessmentTable([...state.assessments].sort((a,b)=>a.due.localeCompare(b.due)))}</section>`;}
function residentsPage(){return heading('RESIDENT CENTER','Every resident, a clearer picture.','Synthetic residents linked to their assessment work and evidence review.',`<button class="primary" data-action="new">+ New assessment</button>`)+`<div class="grid3">${state.assessments.map(a=>{const p=estimatePDPM(a.items);return `<section class="vendor-card"><div class="cardtop"><span class="avatar" style="width:45px;height:45px">${esc(initials(a.name))}</span>${chip('Synthetic','gray')}</div><h3>${esc(a.name)}</h3><span class="sub">${esc(a.id)} · Room ${esc(a.room)}</span><p>${esc(a.type)}<br>ARD ${formatDate(a.ard)} · ${progress(a)}% evidence reviewed<br><span style="color:var(--teal);font-weight:600">Est. $${p.total}/day</span></p><button data-go="assessment/${a.id}">Open assessment →</button></section>`;}).join('')}</div><br>`;}
function qualityPage(){
  const pdpmRows=state.assessments.map(a=>{const p=estimatePDPM(a.items);return {a,p};});
  return heading('QUALITY & READINESS','Better evidence. Better decisions.','Operational review measures from this demonstration; not official CMS quality measures.')+metrics()+`<div class="grid2"><section class="panel"><div class="panelhead"><h2>Review coverage by section</h2></div><div class="pad">${SECTIONS.map(s=>{const n=state.assessments.filter(a=>a.sections[s]?.reviewed).length,p=Math.round(n/Math.max(state.assessments.length,1)*100);return `<div class="barrow"><span>${s}</span><div class="progress"><span style="width:${p}%"></span></div><b>${p}%</b></div>`;}).join('')}</div></section><section class="panel"><div class="panelhead"><h2>PDPM estimate snapshot</h2>${chip('Demo estimates · Not CMS grouper output','amber')}</div><div class="pad"><p style="font-size:11px;line-height:1.8;color:#7a8c70;margin-bottom:16px">Simplified estimates based on GG0130A1, BIMS, and Section I/N data entered in each assessment. Use CMS grouper ${CMS.grouper} with FY2027 ICD-10 mappings for official rates.</p><div class="table-scroll"><table style="white-space:normal"><thead><tr><th>Resident</th><th>GG</th><th>BIMS</th><th>NTA Dx+Meds</th><th>Est. PT/OT</th><th>Est. NTA</th><th>Est. total/day</th></tr></thead><tbody>${pdpmRows.map(({a,p})=>`<tr><td><div class="resident"><span class="avatar" style="font-size:9px">${esc(initials(a.name))}</span><div><strong style="font-size:11px">${esc(a.name)}</strong><small>${esc(a.id)}</small></div></div></td><td>${esc(p.gg)||'—'}</td><td>${p.bims===null?'—':p.bims}</td><td>${(a.items.diagnoses||[]).length+(a.items.meds||[]).length} items<span class="sub">NTA ${p.ntaScore}</span></td><td>$${p.ptRate}/$${p.otRate}</td><td>$${p.ntaRate}</td><td style="font-weight:700;color:var(--teal)">$${p.total}</td></tr>`).join('')}</tbody></table></div></div></section></div><section class="panel"><div class="panelhead"><h2>Submission readiness checklist</h2>${chip('Not connected','amber')}</div><div class="pad"><p style="font-size:12px;line-height:1.8;color:#7a8c70">Complete the items below before connecting to a production CMS submission pipeline.</p><ul class="errors"><li>Official grouper execution and published CMS test vectors (grouper ${CMS.grouper})</li><li>Complete item sets, skip patterns, edits and state Section S</li><li>RN certification, access controls and amendment workflow</li><li>iQIES-compatible package generation and CMS validation reports</li><li>Facility-authorized submission and acceptance reconciliation</li></ul><button style="margin-top:20px" data-go="resources">Open verified CMS sources →</button></div></section>`;
}
function auditPage(){return heading('WORKSPACE ACTIVITY','A record of the work.','Local activity history for this tab. A production audit trail must be server-enforced and immutable.',`<button data-action="export-audit">Export activity JSON</button>`)+`<section class="panel"><div class="panelhead"><h2>Recent activity</h2>${chip(state.logs.length+' events','gray')}</div>${state.logs.length?state.logs.map(l=>`<div class="auditrow"><div class="avatar">${icon('check')}</div><div><small>${esc(new Date(l.at).toLocaleString())} · Demo coordinator</small><p><b>${esc(l.action)}</b></p><p style="color:#7f9074;font-size:11px">${esc(l.detail)}</p></div></div>`).join(''):'<div class="empty">No actions yet.<br>Save an assessment review or process a source sample to create an activity entry.</div>'}</section>`;}
function resourcesPage(){return heading('CURRENT REFERENCE DESK','Know which rules apply.','Sources verified October 2026. References do not mean the complete rules engine is implemented.')+`<div class="grid2"><section class="panel"><div class="panelhead"><h2>Tabula Medica tools</h2>${chip('Live')}</div><a class="resource" target="_blank" rel="noopener noreferrer" href="https://reglens.health/workspace/"><strong>RegLens — SNF Survey Intelligence ↗</strong><p>100+ CMS F-tags, deficiency tracker, 46-item prep checklists by department, CMS Care Compare 5-star lookup, and NPI registry — built for DONs and quality directors.</p></a></section><section class="panel"><div class="panelhead"><h2>Current release references</h2>${chip('Effective now')}</div><a class="resource" target="_blank" rel="noopener noreferrer" href="${CMS.manualUrl}"><strong>MDS 3.0 RAI Manual · ${CMS.rai} ↗</strong><p>Effective October 1, 2026. Confirm detailed coding instructions in the official manual.</p></a><a class="resource" target="_blank" rel="noopener noreferrer" href="${CMS.manualUrl}"><strong>Item sets · ${CMS.itemSet} ↗</strong><p>Track item-set versions separately from manual versions.</p></a><a class="resource" target="_blank" rel="noopener noreferrer" href="${CMS.technicalUrl}"><strong>MDS data specifications · ${CMS.dataSpec} ↗</strong><p>Use the final specification and errata. Complete item and edit validation is not implemented here.</p></a><a class="resource" target="_blank" rel="noopener noreferrer" href="${CMS.technicalUrl}"><strong>PDPM grouper · ${CMS.grouper} ↗</strong><p>FY2027 ICD-10 mappings, applicable target dates beginning October 1, 2026.</p></a></section><section class="panel"><div class="panelhead"><h2>Future release watch</h2>${chip('Draft · not active','amber')}</div><div class="pad"><h3 class="section-title">October 1, 2027</h3><p style="font-size:12px;line-height:1.9;color:#819275">Draft item sets 1.21.1 and draft data specifications 3.11.0 are for a future effective date. They are not activated in the current workspace.</p><div class="notice">The draft GG response value 12 applies to specified future time points. It is not offered in the current admission performance field.</div><a target="_blank" rel="noopener noreferrer" href="${CMS.technicalUrl}">Review CMS technical announcements ↗</a></div></section></div><section class="panel"><div class="panelhead"><h2>From demonstration to a clinical platform</h2></div><div class="pad"><div class="grid3">${[['1. Clinical foundation','Deploy authenticated APIs, tenant and facility isolation, role-based permissions, encrypted storage, immutable audit events, backups and tested recovery. Verify applicable contracts and BAAs.'],['2. Vendor connectivity','Obtain PCC and MatrixCare partner access, sandbox documentation and facility consent. Validate scope, resident linkage, pagination, retries and reconciliation before production.'],['3. Clinical release','Implement complete versioned CMS item sets, scheduling, edits, CAA, signatures, grouper, iQIES exports and acceptance tracking. Run independent clinical and security acceptance tests.']].map(x=>`<div><h3 style="font-size:13px">${x[0]}</h3><p style="font-size:12px;line-height:1.9;color:#839379">${x[1]}</p></div>`).join('')}</div></div></section>`;}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-close aria-label="Close dialog">${icon('close')}</button></div>${body}`;d.querySelector('[data-close]').onclick=()=>d.close();d.showModal();return d;}
function exportJSON(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}
function exportWorklist(){const fields=['id','name','room','type','ard','due','owner','status'];const quote=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const text=[fields.join(','),...state.assessments.map(a=>fields.map(f=>quote(a[f])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='MDS-Synthetic-Worklist.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);log('Worklist exported','Synthetic assessment worklist downloaded.');toast('Synthetic worklist exported.');}
function saveSection(id){
  const a=state.assessments.find(x=>x.id===id),form=$('#section-form');
  if(!a||!form)return;
  const f=new FormData(form);
  const s=state.section;
  const note=String(f.get('note')||'').trim(),reviewed=f.get('reviewed')==='on';
  if(reviewed&&!note){toast('Add an evidence note before marking the section reviewed.');return false;}
  const items={...a.items};
  for(const key of ['C0500','GG0130A1','M0100','M0210','B0200','B0700','B1000','Z0100A','Z0200A','Z0400','Z0500B'])if(f.has(key))items[key]=String(f.get(key));
  for(const gi of GG0130_ITEMS)if(f.has('GG0130_'+gi.id)){items['GG0130_'+gi.id]=String(f.get('GG0130_'+gi.id));if(gi.id==='A1')items.GG0130A1=items['GG0130_'+gi.id];}
  for(const gi of GG0170_ITEMS)if(f.has('GG0170_'+gi.id))items['GG0170_'+gi.id]=String(f.get('GG0170_'+gi.id));
  if(s==='Mood'){for(const k of PHQ_ITEMS){const key='D0200'+k;if(f.has(key))items[key]=String(f.get(key));}}
  if(s==='Diagnoses'){items.diagnoses=f.getAll('diagnosis');}
  if(s==='Medications'){items.meds=f.getAll('med');}
  const next=saveAssessment(a,{items,sections:{...a.sections,[s]:{note,reviewed}}});
  state.assessments[state.assessments.indexOf(a)]=next;
  log('Section review saved',a.id+' · '+s+' · revision '+next.revision);
  render();
  toast('Section saved in this browser tab.');
  return true;
}
function assessmentForm(id){const a=state.assessments.find(x=>x.id===id);const d=modal(a?'Assessment details':'New synthetic assessment',`<form id="assessment-form"><div class="formgrid"><label>Synthetic resident name<input name="name" required maxlength="70" value="${esc(a?.name||'Demo Resident')}"></label><label>Room<input name="room" required maxlength="16" value="${esc(a?.room||'DEMO')}"></label><label>Assessment type<select name="type">${['5-day PPS','OBRA admission','OBRA quarterly','OBRA annual','PPS discharge','Interim payment','Significant change'].map(t=>`<option ${a?.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Coordinator initials<input name="owner" required maxlength="8" value="${esc(a?.owner||'TM')}"></label><label>Assessment reference date<input type="date" name="ard" required value="${esc(a?.ard||state.asof)}"></label><label>Internal completion target<input type="date" name="due" required value="${esc(a?.due||state.asof)}"></label></div><div class="notice">Use synthetic information only. This is a planning record, not a clinical assessment or CMS regulatory scheduling engine.</div><div class="modal-actions"><button type="submit" class="primary">${a?'Save details':'Create assessment'}</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!validDate(values.ard)||!validDate(values.due)){toast('Choose valid dates.');return;}if(a){state.assessments[state.assessments.indexOf(a)]=saveAssessment(a,values);log('Assessment details updated',a.id+' · prior review reopened.');d.close();render();}else{const next={...values,id:'SYN-'+Date.now(),status:'In progress',revision:1,items:{C0500:'',GG0130A1:'',diagnoses:[],meds:[]},sections:Object.fromEntries(SECTIONS.map(s=>[s,{note:'',reviewed:false}]))};state.assessments.push(next);log('Assessment created',next.id+' · synthetic planning record.');d.close();go('assessment/'+next.id);}toast('Assessment saved in this browser tab.');};}
function planModal(id){const v=VENDORS.find(x=>x.id===id);if(!v)return;const p=state.plans[id]||{};const d=modal(v.name+' connection plan',`<form><div class="notice"><b>Planning only.</b> Saving this form does not authorize access or connect the EHR. Do not enter API keys, passwords or patient information.</div><div class="formgrid"><label>Facility identifier (non-secret)<input name="facility" required maxlength="60" value="${esc(p.facility||'DEMO-WILLOW')}"></label><label>Interface approach<select name="approach">${['Vendor-approved API','FHIR R4 — vendor support unverified','HL7 v2 — specification required','Secure file exchange — specification required'].map(x=>`<option ${p.approach===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Access stage<select name="stage">${['Discovery needed','Partner application pending','Sandbox access obtained','Facility authorization obtained'].map(x=>`<option ${p.stage===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Intended scope<select name="scope">${['Read-only clinical evidence','Read-only census and ADT','Read-only demographics'].map(x=>`<option ${p.scope===x?'selected':''}>${x}</option>`).join('')}</select></label></div><ul class="plain-list"><li>Confirm product-specific APIs and permitted data.</li><li>Use server-side credentials and explicit facility scopes.</li><li>Test identity linkage, deduplication, provenance and failures.</li><li>Keep MDS coding and write-back under authorized human review.</li></ul><a href="${v.url}" target="_blank" rel="noopener noreferrer">Open ${v.route} ↗</a><div class="modal-actions"><button type="submit" class="primary">Save offline plan</button></div></form>`);d.querySelector('form').onsubmit=e=>{e.preventDefault();state.plans[id]={...Object.fromEntries(new FormData(e.target)),vendor:v.name,connectionStatus:'not_connected',savedAt:new Date().toISOString()};log('Connection plan saved',v.name+' · no connection or authorization performed.');d.close();render();toast('Plan saved. '+v.name+' remains disconnected.');};}
function runSample(changed=false){const bundle=syntheticBundle();if(changed)bundle.entry[1].resource.valueString='Changed synthetic source: source review required.';const result=normalizeBundle(bundle,'DEMO-WILLOW',state.records);state.records.push(...result.records);state.quarantine.push(...result.quarantine);state.duplicates+=result.duplicates;log('Synthetic FHIR batch processed',`${result.records.length} added; ${result.duplicates} duplicates skipped; ${result.quarantine.length} quarantined.`);render();toast('Batch processed: '+result.records.length+' added, '+result.duplicates+' duplicates, '+result.quarantine.length+' quarantined.');}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.filter='all';go(b.dataset.go);});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render();});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{const form=$('#section-form');if(form&&form.dataset.dirty==='true'){toast('Save the current section before switching.');return;}state.section=b.dataset.section;render();});const form=$('#section-form');if(form){form.oninput=()=>form.dataset.dirty='true';form.onsubmit=e=>{e.preventDefault();saveSection(form.dataset.id);};}for(const selector of ['#global-search','#list-search']){const el=$(selector);if(el)el.onkeydown=e=>{if(e.key==='Enter'){state.query=el.value.trim();if(route()[0]!=='assessments')go('assessments');else render();}};}document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset));}
function action(a,d){if(a==='menu')return $('.sidebar').classList.toggle('open');if(a==='new')return assessmentForm();if(a==='edit-meta')return assessmentForm(d.id);if(a==='export')return exportWorklist();if(a==='save')return saveSection(d.id);if(a==='plan')return planModal(d.vendor);if(a==='sample')return runSample();if(a==='changed-sample')return runSample(true);if(a==='download-sample')return exportJSON('Synthetic-FHIR-Bundle.json',syntheticBundle());if(a==='export-plans')return exportJSON('MDS-Connection-Plans.json',{environment:'demo',liveConnections:0,plans:state.plans});if(a==='export-audit')return exportJSON('MDS-Demo-Activity.json',{immutable:false,environment:'demo',events:state.logs});if(a==='npi-lookup'){const npiVal=$('#npi-input')?.value?.trim();if(!/^\d{10}$/.test(npiVal)){toast('Enter a valid 10-digit NPI number.');return;}const res=$('#npi-result');if(res)res.innerHTML='<span style="font-size:12px;color:#94a3b8">Looking up NPI '+npiVal+'…</span>';fetch('/api/npi/search?number='+encodeURIComponent(npiVal)).then(r=>r.json()).then(data=>{if(!res)return;const r0=data.results?.[0];if(!r0){res.innerHTML='<div class="notice">NPI '+esc(npiVal)+' not found in CMS registry.</div>';return;}const name=r0.basic?.organization_name||(r0.basic?.first_name||'')+' '+(r0.basic?.last_name||'');const addr=r0.addresses?.[0];const addrStr=addr?[addr.address_1,addr.city,addr.state,addr.postal_code?.slice(0,5)].filter(Boolean).join(', '):'Address not available';const enumType=r0.enumeration_type==='NPI-2'?'Organization (NPI-2)':'Individual (NPI-1)';res.innerHTML=`<div style="padding:14px;background:#f0faf2;border-radius:6px;border-left:3px solid var(--teal)"><strong style="font-size:13px">${esc(name.trim())}</strong><div style="font-size:11px;color:#627264;margin-top:4px">${esc(enumType)} · NPI ${esc(r0.number||npiVal)}</div><div style="font-size:11px;color:#627264;margin-top:2px">${esc(addrStr)}</div>${r0.basic?.status?`<div style="font-size:10px;margin-top:4px;color:${r0.basic.status==='A'?'var(--teal)':'#b66a50'}">Status: ${r0.basic.status==='A'?'Active':'Deactivated'}</div>`:''}<div style="font-size:10px;color:#94a3b8;margin-top:6px">Source: CMS NPPES NPI Registry · Real-time · Not linked to this demo facility</div></div>`;}).catch(()=>{if(res)res.innerHTML='<div class="notice">NPI lookup failed. Check connection and try again.</div>';});return;}
if(a==='change-date'){const m=modal('Reference day',`<form><label>Planning reference day<input type="date" name="date" required value="${esc(state.asof)}"></label><div class="modal-actions"><button class="primary">Update calendar</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const date=new FormData(e.target).get('date');if(!validDate(date))return;state.asof=date;log('Reference day changed',date);m.close();render();};return;}const record=state.assessments.find(x=>x.id===d.id);if(a==='validate'&&record){const errors=issues(record);modal('Review gaps',`<div class="notice">These checks cover selected demo fields and evidence notes. They are not the official CMS validation engine.</div>${errors.length?'<ul class="errors">'+errors.map(e=>'<li>'+esc(e.text)+'</li>').join('')+'</ul>':'<p>All local review checks pass.</p>'}`);return;}if(a==='complete'&&record){try{state.assessments[state.assessments.indexOf(record)]=completeReview(record,new Date().toISOString());log('Local review completed',record.id+' · no CMS submission or clinical signature.');render();toast('Local review complete. Nothing was submitted.');}catch(e){toast(e.message);}}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
